// ❌ OLD: The author assumes callbacks run in the order they were
// scheduled. But setTimeout posts a MACROtask while a resolved
// promise schedules a MICROtask. The engine drains all microtasks
// before the next macrotask, so output is NOT call order.
setTimeout(() => console.log('timer'), 0); // ❌ OLD: macrotask — waits for microtasks first
Promise.resolve().then(() => console.log('promise'));

// Actual output:
//   promise
//   timer

// Misreading this ordering leads to race bugs in real code where
// a UI update is expected to reflect a timer result immediately.

// ✅ NEW: queueMicrotask (or Promise.then) makes intent explicit.
// The microtask runs during the current microtask checkpoint, before
// the next macrotask — so we can reason about ordering deterministically.
queueMicrotask(() => console.log('micro')); // ✅ NEW: runs first
setTimeout(() => console.log('macro'), 0); // macrotask: runs after microtasks drain

// Output:
//   micro
//   macro

// When order genuinely matters, prefer await on a promise chain or
// queueMicrotask so the continuation lands in the microtask queue and
// is guaranteed to run before any newly posted timer/IO macrotask.
